#!/usr/bin/env node
// Builds siteguardforms.com.au into dist/ from two sources only:
//   data/catalogue.json   -- generated by Hseq-Dev docs/build_catalogue.py
//                            (packs, prices, documents, what is on sale)
//   content/legal/*.md    -- copied from SiteGuard-Forms app/server/data/legal
//                            by scripts/sync-legal.mjs (the one legal source)
// Nothing about a product or a price is written by hand in this file.
//
// The public DCR extract pinned in dcr.lock (vendored, scripts/lib/dcr.mjs) is
// loaded and verified first: the build fails on a hash mismatch, and on any code
// the catalogue shows or sells that isn't a live public page-A code (retired,
// superseded, not public, or unknown), on a title that differs from the DCR, and
// on a catalogue without the dcr.lock stamp. The DCR never decides what is sold
// or its price.
//
//   node scripts/build-site.mjs               # build; warns about open items
//   node scripts/build-site.mjs --production  # fails on a preview catalogue,
//                                              # open [placeholders] in a legal
//                                              # page, or a banned word
//   node scripts/build-site.mjs --sample-partners  # preview only: partner and
//                                              # review blocks from data/*.sample.json
import { readFile, writeFile, mkdir, rm, cp, readdir } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { esc, frontMatter, render, plain, PLACEHOLDER_RE } from "./lib/md.mjs";
import { loadTrust, partnerStrip, reviewBadge, partnersBody } from "./lib/trust.mjs";
import { loadVideo, introVideo, videoJsonLd } from "./lib/video.mjs";
import { loadPlanning, planningIndexBody, planningStateBody, inspectionsIndexBody, inspectionGroupBody, inspectionGroups, groupPath, icsFor, STATES, STATE_NAMES, statePath } from "./lib/planning.mjs";
import { loadEducation, educationBody, seriesBody, seriesPath, educationJsonLd } from "./lib/education.mjs";
import { loadPinned, checkCatalogue, rev2 } from "./lib/dcr.mjs";
import { loadProductVideos, productVideo } from "./lib/product-videos.mjs";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const DIST = process.env.DIST_DIR ? path.resolve(process.env.DIST_DIR) : path.join(ROOT, "dist");
const CATALOGUE = process.env.CATALOGUE_PATH ? path.resolve(process.env.CATALOGUE_PATH) : path.join(ROOT, "data/catalogue.json");
const PRODUCTION = process.argv.includes("--production");
const SAMPLE_PARTNERS = process.argv.includes("--sample-partners");
// Partners, affiliates and the Google review link (data/partners.json,
// data/google-reviews.json; scripts/lib/trust.mjs). Loaded in build().
let TRUST = { partners: [], reviews: {} };
// Landing-page introduction video (data/intro-video.json;
// scripts/lib/video.mjs). Nothing shows until it is filled in. server.js
// reads the same file for the CSP, so restart after changing it.
let VIDEO = null;
// Planning calendar and inspection planner (data/planning-calendar.json,
// data/inspection-planner.json; scripts/lib/planning.mjs). /planning/.
let PLANNING = { cal: null, insp: null };
// SiteGuard Education hub (data/education.json, identical to siteguard-website's;
// scripts/lib/education.mjs). server.js reads it too, for the CSP.
let EDU = null;
// FORMS product videos on the pack pages (data/product-videos.json;
// scripts/lib/product-videos.mjs). Placeholders until each is published.
let PRODUCT_VIDEOS = null;
// Beta: the shop can be browsed but nothing can be bought or subscribed to
// (data/site-mode.json, read by server.js too). Dan, 22 Oct 2026.
const SITE_MODE_PATH = process.env.SITE_MODE_PATH ? path.resolve(process.env.SITE_MODE_PATH) : path.join(ROOT, "data/site-mode.json");
const SITE_MODE = JSON.parse(await readFile(SITE_MODE_PATH, "utf8").catch(() => "{}"));
const BETA = SITE_MODE.beta === true;
// The SiteGuard App and Audit stage (data/site-mode.json app_status, the same
// field and values as siteguard-website: "coming_soon", "presale", "live";
// separate from beta, which is FORMS ordering). The founding-offer panel shows
// only while it is "presale" (from March 2027, on Dan's go). App modules open
// June 2027.
export const APP_STATUSES = ["coming_soon", "presale", "live"];
const APP_STATUS = SITE_MODE.app_status ?? "coming_soon";
const FOUNDING = APP_STATUS === "presale";
// Optional same-origin endpoint answering {"remaining": n} (the founding API,
// rollout P2); until it exists the panel says "the first 20 places" (static).
const FOUNDING_PLACES_API = SITE_MODE.founding_places_api ?? "";
export const FOUNDING_PLACES = 20;

const ORIGIN = (process.env.SITE_ORIGIN ?? "https://www.siteguardforms.com.au").replace(/\/$/, "");
const APP_URL = (process.env.FORMS_APP_URL ?? "https://app.siteguardforms.com.au").replace(/\/$/, "");
const SYSTEMS_URL = (process.env.SYSTEMS_URL ?? "https://www.siteguardsystems.com.au").replace(/\/$/, "");
// The founding-offer page lives on the Systems site (rollout P4).
const FOUNDING_URL = `${SYSTEMS_URL}/app/founding-offer/`;

// Words the marketing pages must never use (websites brief Rev02, WP5). The
// legal pages are exempt: they are solicitor-controlled and use some of these
// words to say what SiteGuard does NOT claim.
export const BANNED = /\b(compliant|certified|endorsed|guarantee[sd]?|4801|coming soon|rolling out|in progress|quarterly|money[- ]back)\b/gi;
const BANNED_ALLOWED = [/Certified Lead Auditor/gi];
// Gated products and markets (rebaseline, 31 Oct 2026): never listed, priced or
// teased on a customer page. "Core Management System" is a FORMS pack name, not
// the gated CORE product, so CORE counts only in capitals and not before
// "Management System".
export const GATED = /\bSiteGuard AI\b|\brobotics?\b|\bNew Zealand\b|\boverseas markets?\b|\binternational markets?\b|\bCORE\b(?! Management System)/g;

const LEGAL_PAGES = [
  { file: "terms-of-sale.md", slug: "terms-of-sale", nav: "Terms of Sale" },
  { file: "refunds.md", slug: "refunds", nav: "Refunds and cancellations" },
  { file: "privacy.md", slug: "privacy", nav: "Privacy Policy" },
  { file: "disclaimer.md", slug: "document-use-disclaimer", nav: "Document Use Disclaimer" },
  { file: "consultant-licence.md", slug: "consultant-licence", nav: "Consultant Licence" },
  { file: "terms-of-use.md", slug: "app-terms", nav: "FORMS App Terms of Use" },
  { file: "website-terms.md", slug: "website-terms", nav: "Website Terms of Use" },
];

const GROUPS = {
  "trade-packs": { path: "/trade-packs/", title: "Trade packs", nav: "Trade packs" },
  "builder-packs": { path: "/builder-packs/", title: "Builder packs", nav: "Builder packs" },
  "management-systems": { path: "/management-systems/", title: "Management systems", nav: "Management systems" },
  "specialist-packs": { path: "/specialist-packs/", title: "Specialist packs", nav: "Specialist packs" },
  "consultants": { path: "/consultants/", title: "For consultants", nav: "Consultants" },
};

const money = (n) => "$" + Number(n).toLocaleString("en-AU");
// Customer-facing prices are A$ ex GST and say "+GST" (rebaseline standing rules).
const exGst = (n, per = "") => `${money(n)}<small> +GST${per}</small>`;
// Set in build(): the consultants page, its nav links and its mentions appear
// only when a consultant plan is on sale (no "coming soon").
let CONSULTANTS_ON = false;
const problems = [];
const pages = [];
// DCR warnings (a retired code neither shown nor sold): reported, never blocking.
const dcrWarnings = [];
let DCR_PIN = null;

/** Loads and verifies the pinned DCR, then checks the catalogue against it. */
async function checkDcr(cat) {
  let pinned;
  try {
    pinned = await loadPinned(ROOT);
  } catch (e) {
    console.error(`DCR: the public extract pinned in dcr.lock does not verify: ${e.message}`);
    console.error("Fix vendor/siteguard-dcr or dcr.lock (see README, \"DCR\"). The build stops here.");
    process.exit(1);
  }
  DCR_PIN = { revision: pinned.dcr.revision, sha256: pinned.dcr.sourceSha256, public_sha256: pinned.dcr.sha256 };
  for (const f of checkCatalogue(cat, pinned)) {
    if (f.severity === "error") problems.push(`DCR: [${f.kind}] ${f.message}`);
    else dcrWarnings.push(f);
  }
}

// -- layout --------------------------------------------------------------------

function header(current) {
  const links = [
    ["/trade-packs/", "Trade packs"], ["/builder-packs/", "Builder packs"],
    ["/management-systems/", "Management systems"], ["/specialist-packs/", "Specialist packs"],
    ["/documents/", "Single documents"], ["/consultants/", "Consultants"],
    ["/how-ordering-works/", "How it works"],
  ].filter(([href]) => CONSULTANTS_ON || href !== "/consultants/");
  const nav = links.map(([href, label]) =>
    `<a href="${href}"${current.startsWith(href) ? ' aria-current="page"' : ""}>${label}</a>`).join("");
  return `<a class="skip" href="#main">Skip to content</a>
<header class="site-header">
  <div class="wrap header-row">
    <a class="brand" href="/"><img src="/assets/shield.png" alt="" width="34" height="44"><span class="brand-name">SiteGuard <b>FORMS</b></span></a>
    <button class="menu-toggle" type="button" aria-expanded="false" aria-controls="site-nav">Menu</button>
    <nav class="nav" id="site-nav" aria-label="Main">${nav}<a class="cart-link" href="/cart/">Cart <span data-cart-count>(0)</span></a></nav>
  </div>
</header>`;
}

