  if (SAMPLE_PARTNERS) problems.push(`data: built with SAMPLE partners and reviews (--sample-partners)${PRODUCTION ? "; a production build can't use sample data" : " (open item: preview only)"}`);
  const vid = await loadVideo(ROOT);
  VIDEO = vid.video;
  for (const p of vid.problems) problems.push(`data: ${p}`);
  PLANNING = await loadPlanning(ROOT);
  PRODUCT_VIDEOS = await loadProductVideos(ROOT);
  for (const p of PRODUCT_VIDEOS.problems) problems.push(`data: ${p}`);
  if (!APP_STATUSES.includes(APP_STATUS)) problems.push(`data: site-mode.json app_status must be one of ${APP_STATUSES.join(", ")} (it is ${JSON.stringify(APP_STATUS)})`);
  if (FOUNDING_PLACES_API && !/^\/[A-Za-z0-9/_-]*$/.test(FOUNDING_PLACES_API)) problems.push("data: site-mode.json founding_places_api must be a same-origin path such as /api/founding/places");
  const edu = await loadEducation(ROOT);
  EDU = edu.edu;
  for (const p of edu.problems) problems.push(`data: ${p}`);
  for (const p of PLANNING.problems) problems.push(/open item/.test(p) ? p : `data: ${p}`);
  const cat = JSON.parse(await readFile(CATALOGUE, "utf8"));
  await checkDcr(cat);
  if (PRODUCTION && cat.preview) problems.push("catalogue.json is a PREVIEW build (generated with --preview); regenerate without it");
  const titles = new Map(cat.documents.map((d) => [d.code, d.title]));
  for (const p of cat.packs) for (const c of p.documents) if (!titles.has(c)) titles.set(c, c);
  const shown = cat.packs.filter((p) => p.show && p.prices);
  const inGroup = (g) => shown.filter((p) => p.group === g);
  CONSULTANTS_ON = inGroup("consultants").some((p) => p.id !== "consultant:seat");
  const trades = cat.trades.map((t) => ({ ...t, packs: shown.filter((p) => p.trade === t.code) })).filter((t) => t.packs.length);
  const f = cat.facts;
  const preview = cat.preview;
  // The shop's own numbers count what can be bought here (every listed
  // document in a preview), not the whole library.
  const onSale = cat.documents.filter((d) => preview || d.sellable);
  const shop = {
    documents: onSale.length,
    swms: onSale.filter((d) => d.family === "SWMS").length,
    trades: trades.length,
  };
  const fromOf = (packs) => {
    const v = packs.map((p) => p.prices.one_off ?? p.prices.annual);
    return v.length ? Math.min(...v) : null;
  };

